style:
/* 研路 —— 藏青页眉与矩形标牌标题，报考信息成表 */

.tw-yanlu.layout-band.resume-paper .paper-header {
  margin: -15mm -15mm 7.5mm;
  padding: 10mm 15mm 7mm;
  align-items: flex-start;
  gap: 7mm;
  background: var(--paper-accent);
  border: none;
  color: #fff;
  print-color-adjust: exact;
}

.tw-yanlu.layout-band.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-yanlu.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 24mm;
  height: 32mm;
  border: 0.5mm solid rgba(255, 255, 255, 0.55);
  border-radius: 0;
  box-shadow: none;
  print-color-adjust: exact;
}

.tw-yanlu.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-yanlu.layout-band.resume-paper .paper-name {
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.2);
  letter-spacing: 0.1em;
}

.tw-yanlu.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: rgba(255, 255, 255, 0.78);
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-yanlu.layout-band.resume-paper .paper-role {
  margin-top: 2mm;
  color: rgba(255, 255, 255, 0.92);
  font-size: calc(var(--paper-base-size) * 1.02);
  font-weight: 500;
  letter-spacing: 0.04em;
}

.tw-yanlu.layout-band.resume-paper .paper-contacts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 4mm;
  color: rgba(255, 255, 255, 0.9);
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-yanlu.layout-band.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
}

.tw-yanlu.layout-band.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-yanlu.layout-band.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: rgba(255, 255, 255, 0.62);
}

/* 模块标题：藏青标牌，右端切一刀 */
.tw-yanlu.layout-band.resume-paper .paper-style-block .paper-section__title {
  display: inline-flex;
  align-items: center;
  gap: 2mm;
  margin-bottom: 3.6mm;
  padding: 1.2mm 5mm 1.2mm 3.2mm;
  background: var(--paper-accent);
  border-radius: 0;
  clip-path: polygon(0 0, 100% 0, calc(100% - 2.6mm) 100%, 0 100%);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.02);
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-yanlu.layout-band.resume-paper .paper-section__body {
  color: #26313f;
}

.tw-yanlu.layout-band.resume-paper .paper-item-title {
  color: #17222f;
}

.tw-yanlu.layout-band.resume-paper .paper-item-period {
  color: #6d7b8c;
}

.tw-yanlu.layout-band.resume-paper .paper-item-sub {
  color: #46556a;
}

/* 报考信息排成两列表格 */
.tw-yanlu.layout-band.resume-paper .paper-facts {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  border-top: 0.25mm solid #ccd5e1;
  border-left: 0.25mm solid #ccd5e1;
}

.tw-yanlu.layout-band.resume-paper .paper-facts > div {
  flex-direction: row;
  align-items: baseline;
  gap: 3mm;
  padding: 1.6mm 2.6mm;
  border-right: 0.25mm solid #ccd5e1;
  border-bottom: 0.25mm solid #ccd5e1;
}

.tw-yanlu.layout-band.resume-paper .paper-facts span {
  flex: 0 0 auto;
  color: #6d7b8c;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-yanlu.layout-band.resume-paper .paper-facts strong {
  font-weight: 600;
}

.tw-yanlu.layout-band.resume-paper .paper-rich ul,
.tw-yanlu.layout-band.resume-paper .paper-rich ol {
  margin-top: 1mm;
  padding-left: 1.1em;
}

.tw-yanlu.layout-band.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

.tw-yanlu.layout-band.resume-paper .paper-note__tag {
  color: var(--paper-accent);
  font-weight: 600;
}

.tw-yanlu.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #e2e7ee;
  color: #9ba5b3;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-yanlu.resume-paper .paper-rich ul[data-list],
.tw-yanlu.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-yanlu.resume-paper .paper-rich ul[data-list] > li,
.tw-yanlu.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-yanlu.resume-paper .paper-rich ul[data-list] > li::before,
.tw-yanlu.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-yanlu.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-yanlu.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-yanlu.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-yanlu.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-yanlu.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
